method SortNumbers(numbers: string) returns (sorted: string)
    requires IsValidInput(numbers)
    ensures IsSortedOutput(sorted, numbers)

    // Auxiliary methods to specify the requirements
    method IsValidInput(numbers: string) returns (valid: bool)
        // Valid if it consists of space-delimited words that are numbers from zero to nine
        ensures valid <==> (forall i: int | 0 <= i < CountWords(numbers) :: IsNumberWord(GetWord(numbers, i)))

    method IsSortedOutput(sorted: string, input: string) returns (valid: bool)
        // The output must consist of the same number words as the input and must be sorted
        ensures valid <==> (CountWords(sorted) == CountWords(input) && 
                             forall i: int | 0 <= i < CountWords(sorted) - 1 :: 
                                 GetWord(sorted, i) <= GetWord(sorted, i + 1) &&
                             forall i: int | 0 <= i < CountWords(input) :: 
                                 Exists j: int | 0 <= j < CountWords(sorted) :: GetWord(input, i) == GetWord(sorted, j))

    // Helper methods for word manipulation
    method CountWords(s: string) returns (count: int)
        // Count the number of space-delimited words in the string

    method GetWord(s: string, index: int) returns (word: string)
        // Get the word at the specified index from the space-delimited string

    method IsNumberWord(word: string) returns (isNumber: bool)
        // Check if the word is one of the valid number words: 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'
```

